fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Only iterate over parent indices: 0 <= i < n/2
    // Because any node beyond floor(n/2) - 1 are leaf nodes with no children
    for i in 0..(n / 2) {
        let left = 2 * i + 1;
        if left < n {
            // If left child is strictly less than parent, not a min-heap.
            if a[left] < a[i] {
                return false;
            }
        }

        let right = 2 * i + 2;
        if right < n {
            // If right child is strictly less than parent, not a min-heap.
            if a[right] < a[i] {
                return false;
            }
        }
    }
    // All parent-child relations satisfy min-heap property
    true
}